        connector.SaleAddress = "г. Москва, ул. Ленина, д. 1"; // адрес расчётов
        connector.SaleLocation = "Торговый зал"; // место расчётов
        connector.TextBefore = "Текст 1"; // текст до фискальной части (на ленте, не в ФН как позиция)
